let unique=0;
const format=v=>v===null?'未定义':v!==0&&(Math.abs(v)<1e-4||Math.abs(v)>=1e7)?v.toExponential(4):Number(v.toPrecision(6)).toLocaleString('zh-CN',{maximumFractionDigits:6});
