  need(array(d.columns,8)&&d.columns.every(c=>c&&id(c.id)&&txt(c.label,100))&&unique(d.columns)&&array(d.items,100,0),'看板列或项目无效');const items=d.items.map(i=>{need(i&&id(i.id)&&txt(i.label,240)&&d.columns.some(c=>c.id===i.column),'项目引用无效');return{id:i.id,label:i.label,column:i.column,done:i.done===true};});need(unique(items),'项目ID重复');return{...base,columns:d.columns.map(c=>({id:c.id,label:c.label})),items};
